{"summary": "Inspect Answer step1 cells and formats across columns B-K", "command": "python3 - <<'PY'
import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
ws=wb['Answer']
for r in range(1,8):
    row=[]
    for c in range(1,12):
        v=ws.cell(r,c).value
        row.append(v)
    print(r, row)
print('--- step1 target rows 3-6, all cols with coordinates/value')
for r in range(3,7):
    for c in range(1,12):
        cell=ws.cell(r,c)
        if cell.value is None and cell.data_type=='n':
            pass
    # print non-empty labels
    for c in range(1,12):
        v=ws.cell(r,c).value
        if v is not None:
            print(r, get_column_letter(c), v)
PY"}

